int main(){try{PlanarControls();ParticleControls();RandomLawControls();BoundaryControls();ResumeControls();Check(std::string(ForwardAngularLineageVersion)=="hylios_angular_lineage_v2","observational version changes independently of physical model");IndividualClosure();ProlateAndPolicies();OneChildReturn();ComplexAcquisitions();ResidualUnknownReturn();PointSourceCertificates();FailureAndCopy();EveryPartition();std::cout<<"PASS "<<checks<<" coupled angular lineage checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
